@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + number : int
  + numberOfSeats : int
  + isSmoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

class BillItem {
  + quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "1..*" Table : assigned to
Waiter "1" -- "*" Customer : serves
Customer "1" -- "*" Bill : receives
Bill "1" *-- "*" BillItem : consists of
BillItem "*" -- "1" Dish : includes

@enduml

